class WorkoutSession extends DataClass implements Insertable<WorkoutSession> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final bool deleted;

  /// `deviceId` of the device that wrote the row last (sync tie-break).
  final String lastModifiedBy;
  final String? programDayId;
  final String? name;
  final DateTime startedAt;
  final DateTime? endedAt;
  final String? notes;

  /// Optional, for bodyweight exercises.
  final double? bodyWeightKg;

  /// End of the current rest, if resting. Stored as a timestamp so the rest
  /// survives the app going to the background or being killed.
  final DateTime? restEndsAt;

  /// Set while the session is paused.
  final DateTime? pausedAt;

  /// Total paused time of past pauses, excluded from the session duration.
  final int pausedSeconds;
  const WorkoutSession({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.deleted,
    required this.lastModifiedBy,
    this.programDayId,
    this.name,
    required this.startedAt,
    this.endedAt,
    this.notes,
    this.bodyWeightKg,
    this.restEndsAt,
    this.pausedAt,
    required this.pausedSeconds,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted'] = Variable<bool>(deleted);
    map['last_modified_by'] = Variable<String>(lastModifiedBy);
    if (!nullToAbsent || programDayId != null) {
      map['program_day_id'] = Variable<String>(programDayId);
    }
    if (!nullToAbsent || name != null) {
      map['name'] = Variable<String>(name);
    }
    map['started_at'] = Variable<DateTime>(startedAt);
    if (!nullToAbsent || endedAt != null) {
      map['ended_at'] = Variable<DateTime>(endedAt);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || bodyWeightKg != null) {
      map['body_weight_kg'] = Variable<double>(bodyWeightKg);
    }
    if (!nullToAbsent || restEndsAt != null) {
      map['rest_ends_at'] = Variable<DateTime>(restEndsAt);
    }
    if (!nullToAbsent || pausedAt != null) {
      map['paused_at'] = Variable<DateTime>(pausedAt);
    }
    map['paused_seconds'] = Variable<int>(pausedSeconds);
    return map;
  }

  WorkoutSessionsCompanion toCompanion(bool nullToAbsent) {
    return WorkoutSessionsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deleted: Value(deleted),
      lastModifiedBy: Value(lastModifiedBy),
      programDayId: programDayId == null && nullToAbsent
          ? const Value.absent()
